import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Carpentry","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/carpentry.md","filePath":"en/guide/professions/carpentry.md"}'),r={name:"en/guide/professions/carpentry.md"};function o(s,e,l,d,c,h){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="carpentry" tabindex="-1">Carpentry <a class="header-anchor" href="#carpentry" aria-label="Permalink to &quot;Carpentry&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> This page describes the intended redesign, not confirmed live mechanics. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/en/game-design/professions/carpentry.html">full design specification</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Carpentry turns wood knowledge into equipment, construction and useful field structures.</li><li>Bowmaking is a learned Carpentry/Archery technique path, not an automatic skill reward.</li><li>Material preparation and joinery matter; construction and migration rules remain open.</li></ul><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Carpentry transforms wood through seasoning, selection, cutting, shaping, joining, assembly and finishing. Grain, moisture, joinery and treatment should matter without requiring microscopic woodworking simulation.</p><h2 id="why-take-it-into-the-field" tabindex="-1">Why take it into the field? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Permalink to &quot;Why take it into the field?&quot;">​</a></h2><p>Proposed outputs range from furniture, containers and weapon handles to shields, camp structures, mine supports, bridges and fortifications. Camping, <a href="/Syrolands-Public/en/guide/professions/mining.html">Mining</a>, <a href="/Syrolands-Public/en/guide/professions/blacksmithing.html">Blacksmithing</a> and <a href="/Syrolands-Public/en/guide/professions/tinkering.html">Tinkering</a> create useful collaborations; placement and protection rules remain open.</p><h2 id="bowmaking-and-fletching" tabindex="-1">Bowmaking and Fletching <a class="header-anchor" href="#bowmaking-and-fletching" aria-label="Permalink to &quot;Bowmaking and Fletching&quot;">​</a></h2><p>Bowmaking is a learned technique path based primarily on Carpentry and Archery, with optional Tailoring and Blacksmithing support. It is not a standalone skill in this proposal, and ordinary Carpentry does not automatically teach it. Selecting and seasoning a stave, shaping, tillering, stringing, tuning and test firing build toward a Master Bowyer identity. Arrows combine shafts, heads, fletching and assembly; their exact roles remain proposed. Reconciliation of any existing Bowcraft skill is still pending.</p><h2 id="learning-and-specialization" tabindex="-1">Learning and specialization <a class="header-anchor" href="#learning-and-specialization" aria-label="Permalink to &quot;Learning and specialization&quot;">​</a></h2><p>A Woodworker’s Journal tracks materials and techniques learned from teachers, manuscripts, challenges and exploration. <a href="/Syrolands-Public/en/guide/professions/overview.html">Shared progression and batches</a> apply. Construction and Bowmaking provide paths; Luthiery and ship components remain future directions. <a href="/Syrolands-Public/en/guide/professions/lumberjacking.html">Lumberjacking</a> provides timber expertise, while <a href="/Syrolands-Public/en/guide/items/item-quality.html">item quality</a> describes the result envelope.</p><p><a href="/Syrolands-Public/en/guide/professions/overview.html">All professions</a> · <a href="/Syrolands-Public/en/game-design/professions/carpentry.html">Full design specification</a></p>',13)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
